'use strict';
const DrillJournal=(()=>{
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const avatar=n=>'<span class="discussion-avatar">'+(/^api\/stats\/avatars\/\d+\/[a-f0-9]+$/.test(n.avatar||'')?'<img src="'+esc(n.avatar)+'" width="36" height="36" loading="lazy" alt="'+esc(n.name)+'的头像">':esc(n.name?.slice(0,1)||'队'))+'</span>';
 function note(n,me,history=false){return '<article class="drill-note">'+avatar(n)+'<div class="drill-note-main"><header><strong>'+esc(n.name)+'</strong><small>#'+n.number+'</small>'+(history?'<time>'+esc(n.heldOn||'日期未设置')+' · '+esc(n.trainingName)+'</time>':'')+'</header>'+(n.problems?'<section><b>存在的问题</b><div class="light-markdown">'+LiteMarkdown.render(n.problems)+'</div></section>':'')+(n.progress?'<section class="drill-note-progress"><b>相比上次的进步</b><div class="light-markdown">'+LiteMarkdown.render(n.progress)+'</div></section>':'')+(!history&&me?.id===n.player?'<button type="button" class="drill-note-edit" data-edit-note="'+n.id+'">编辑我的记录</button>':'')+'</div></article>';}
 function init(d){
  document.addEventListener('click',event=>{for(const menu of document.querySelectorAll('.drill-card-menu[open]'))if(!menu.contains(event.target))menu.open=false;});
  const views=new Map();let historyId=null,historyHost=null,historyToken=0,historyLoad=null;
  function renderTraining(host,training,editable,revision){const key=training.id+':'+(d.getMe()?.id||'guest');let view=views.get(host.id);if(!view||view.key!==key){host.replaceChildren();view={key,cards:new Map()};views.set(host.id,view);}const ids=new Set(training.drills.map(x=>x.id));for(const [id,card] of view.cards)if(!ids.has(id)){card.el.remove();view.cards.delete(id);}
   if(!ids.size){host.innerHTML='<p class="stats-empty">还没有安排 Drill。</p>';return;}
   [...host.children].find(el=>el.classList.contains('stats-empty'))?.remove();
   for(const drill of training.drills){let card=view.cards.get(drill.id);if(!card){card=mountCard(host,view,training,drill);view.cards.set(drill.id,card);}card.update(drill,editable,revision);}
  }
  function mountCard(host,view,training,drill){const el=document.createElement('article');el.className='training-drill-card';el.dataset.drillJournal=drill.id;
   el.innerHTML='<div class="drill-card-header"><button type="button" class="drill-demo" data-team-drill="'+esc(drill.id)+'"><span class="drill-play" aria-hidden="true">▶</span><span><strong></strong><small>查看演示</small></span></button><button type="button" class="quiet-btn drill-note-toggle" data-j="toggle" aria-expanded="false"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M9 5H5v15h15v-4M17 3l4 4-10 10-5 1 1-5Z"/></svg><span data-j="count">记备注</span></button><details class="drill-card-menu"><summary aria-label="Drill 更多操作">···</summary><div><button type="button" class="danger-text" data-drill-remove="'+esc(drill.id)+'">移出本次训练</button></div></details></div><section class="drill-note-panel" data-j="panel" hidden><div data-j="notes" class="drill-note-list"></div><p data-j="error" class="discussion-status" role="status"></p><button type="button" class="quiet-btn" data-j="login">登录队员身份后记录</button><button type="button" class="quiet-btn" data-j="write">＋ 记录问题与进步</button><form class="drill-note-form" data-j="form" hidden><label>这次普遍存在的问题<textarea data-j="problems" maxlength="800" rows="2" placeholder="例如：切入偏早、回传后清空不及时"></textarea></label><label>相比上次进步的地方<textarea data-j="progress" maxlength="800" rows="2" placeholder="例如：沟通更及时，接盘后的观察更充分"></textarea></label><div class="drill-note-form-actions"><button type="button" class="quiet-btn" data-j="cancel">收起</button><button type="submit" class="primary" data-j="save">保存我的记录</button></div></form></section>';
   host.append(el);const panelId=host.id+'-'+drill.id+'-notes';el.querySelector('[data-j=panel]').id=panelId;el.querySelector('[data-j=toggle]').setAttribute('aria-controls',panelId);const $=s=>el.querySelector(s),panel=$('[data-j="panel"]');let notes=[],signature='',loaded='',loading=false,pending=false,dirty=false,serial=0,ownId=null,writing=false;const current=()=>views.get(host.id)===view&&el.parentElement===host;
   function draw(){const me=d.getMe();$('[data-j="form"]').hidden=!me||!writing;$('[data-j="write"]').hidden=!me||writing;$('[data-j="login"]').hidden=!!me;$('[data-j="notes"]').innerHTML=notes.length?notes.map(n=>note(n,me)).join(''):'<p class="stats-empty">还没有练习备注。</p>';ownId=notes.find(n=>n.player===me?.id)?.id||null;$('[data-j="write"]').hidden=!me||writing||!!ownId;$('[data-j="save"]').textContent=pending?'正在保存…':ownId?'更新我的记录':'保存我的记录';}
   function hydrate(){if(dirty)return;const own=notes.find(n=>n.player===d.getMe()?.id);if(own){$('[data-j="problems"]').value=own.problems;$('[data-j="progress"]').value=own.progress;}}
   for(const input of el.querySelectorAll('textarea')){input.oninput=()=>dirty=true;MarkdownEditor.mount(input,{label:(input.dataset.j==='problems'?'问题':'进步')+'文字格式',inputLabel:input.dataset.j==='problems'?'这次普遍存在的问题':'相比上次进步的地方'});}
   async function load(){if(loading||pending)return;loading=true;const version=signature,request=++serial;$('[data-j="error"]').textContent='正在读取练习备注…';try{const result=await d.api('stats/trainings/'+training.id+'/drills/'+drill.id+'/notes');if(!current()||request!==serial)return;notes=result.notes;loaded=version;draw();hydrate();$('[data-j="error"]').textContent='';}catch(error){if(current())$('[data-j="error"]').textContent=error.message;}finally{loading=false;}}
   function open(){if(!drill.noteCount&&d.getMe())writing=true;panel.hidden=false;draw();$('[data-j="toggle"]').setAttribute('aria-expanded','true');load();}el.openNotes=open;$('[data-j="toggle"]').onclick=()=>{if(panel.hidden)open();else{panel.hidden=true;$('[data-j="toggle"]').setAttribute('aria-expanded','false');}};$('[data-j="write"]').onclick=()=>{writing=true;draw();hydrate();$('[data-j="problems"]').focus({preventScroll:true});};$('[data-j="cancel"]').onclick=()=>{writing=false;draw();};$('[data-j="login"]').onclick=()=>d.login();
   el.onclick=event=>{const button=event.target.closest('[data-edit-note]');if(!button)return;const found=notes.find(n=>n.id===Number(button.dataset.editNote));if(!found||found.player!==d.getMe()?.id)return;writing=true;draw();$('[data-j="problems"]').value=found.problems;$('[data-j="progress"]').value=found.progress;$('[data-j="form"]').scrollIntoView({block:'nearest',behavior:'smooth'});};
   $('[data-j="form"]').onsubmit=async event=>{event.preventDefault();if(pending||!d.getMe())return;const problems=$('[data-j="problems"]').value.trim(),progress=$('[data-j="progress"]').value.trim();if(!problems&&!progress){$('[data-j="error"]').textContent='请至少填写一个问题或一项进步。';return;}pending=true;for(const input of el.querySelectorAll('textarea,button[data-j="save"]'))input.disabled=true;draw();try{const result=await d.api('stats/trainings/'+training.id+'/drills/'+drill.id+'/notes',{method:'POST',body:JSON.stringify({problems,progress})});if(current()){notes=result.notes;dirty=false;writing=false;hydrate();$('[data-j="error"]').textContent='已保存，可在这个 Drill 的训练记录中回看。';}await d.refresh(true);d.toast('练习备注已保存。');}catch(error){if(current())$('[data-j="error"]').textContent=error.message;d.toast(error.message);}finally{pending=false;if(current()){for(const input of el.querySelectorAll('textarea,button[data-j="save"]'))input.disabled=false;draw();}}};
   return{el,update(next,editable,revision){$('.drill-demo strong').textContent=next.name;$('[data-drill-remove]').hidden=!editable;$('.drill-card-menu').hidden=!editable;$('[data-j="count"]').textContent=next.noteCount?'备注 · '+next.noteCount:'记备注';$('[data-j="form"]').hidden=!d.getMe()||!writing;$('[data-j="write"]').hidden=!d.getMe()||writing||!!ownId;$('[data-j="login"]').hidden=!!d.getMe();signature=String(revision)+':'+(next.noteVersion||0);if(!panel.hidden&&loaded!==signature)load();}};
  }
  function expand(host,id){const el=[...host.querySelectorAll('[data-drill-journal]')].find(x=>x.dataset.drillJournal===id);if(el){el.openNotes();el.scrollIntoView({block:'start',behavior:'smooth'});}}
  function historyNote(n){return '<article class="drill-history-note"><header>'+avatar(n)+'<div><strong>'+esc(n.name)+'</strong><small>#'+n.number+'</small></div></header><div class="drill-history-observations">'+(n.problems?'<section><h4>存在的问题</h4><div class="light-markdown">'+LiteMarkdown.render(n.problems)+'</div></section>':'')+(n.progress?'<section class="drill-history-progress"><h4>相比上次的进步</h4><div class="light-markdown">'+LiteMarkdown.render(n.progress)+'</div></section>':'')+'</div></article>';}
  function renderHistory(host,id,visible=false){if(!host)return;if(historyHost===host&&historyId===id){if(visible)historyLoad?.();return;}historyHost=host;historyId=id;historyLoad=null;const token=++historyToken;host.hidden=!id;host.replaceChildren();if(!id)return;
   host.innerHTML='<header class="drill-history-heading"><p data-j="sessions"></p><button type="button" class="quiet-btn" data-j="refresh" aria-label="刷新训练记录">↻ 刷新</button></header><div class="drill-history-list" data-j="history"></div><p class="discussion-status" data-j="history-status" role="status"></p><button type="button" class="quiet-btn" data-j="more" hidden>加载更早的记录</button>';
   const $=s=>host.querySelector(s);let pending=false,loaded=false,offset=0,notes=[];
   function draw(){const groups=new Map();for(const n of notes){if(!groups.has(n.trainingId))groups.set(n.trainingId,[]);groups.get(n.trainingId).push(n);}$('[data-j="history"]').innerHTML=[...groups.values()].map(group=>'<section class="drill-history-session"><header><div><time>'+esc(group[0].heldOn||'日期未设置')+'</time><h3>'+esc(group[0].trainingName)+'</h3></div><small>'+group.length+' 份记录</small></header><div class="drill-history-session-notes">'+group.map(historyNote).join('')+'</div></section>').join('')||'<div class="drill-history-empty"><strong>还没有训练记录</strong><p>在训练安排中添加这个 Drill 后，队员可记录问题和进步。</p></div>';}
   async function load(reset=false){if(pending)return;pending=true;$('[data-j="refresh"]').disabled=true;$('[data-j="more"]').disabled=true;$('[data-j="history-status"]').textContent='正在读取训练记录…';try{const result=await d.api('stats/drills/'+id+'/notes?offset='+(reset?0:offset||0));if(token!==historyToken)return;notes=(reset?result.notes:[...notes,...result.notes]).filter((n,i,all)=>all.findIndex(x=>x.id===n.id)===i);loaded=true;draw();$('[data-j="sessions"]').textContent=result.trainingCount+' 次训练 · '+result.total+' 份记录';offset=result.nextOffset;$('[data-j="more"]').hidden=offset===null;$('[data-j="history-status"]').textContent='';}catch(error){if(token===historyToken)$('[data-j="history-status"]').textContent=error.message;}finally{pending=false;if(token===historyToken){$('[data-j="refresh"]').disabled=false;$('[data-j="more"]').disabled=false;}}}
   historyLoad=()=>{if(!loaded)load(true);};$('[data-j="refresh"]').onclick=()=>load(true);$('[data-j="more"]').onclick=()=>load();if(visible)historyLoad();
  }
  return{renderTraining,expand,renderHistory};
 }
 return{init};
})();
